-- Tüm Türkiye ilçeleri. Şehir UUID’leri plaka koduyla eşleşir.

update public.locations set slug = 'istanbul-kadikoy' where type = 'district' and slug = 'kadikoy';
update public.locations set slug = 'istanbul-besiktas' where type = 'district' and slug = 'besiktas';
update public.locations set slug = 'istanbul-sisli' where type = 'district' and slug = 'sisli';
update public.locations set slug = 'istanbul-uskudar' where type = 'district' and slug = 'uskudar';
update public.locations set slug = 'istanbul-bakirkoy' where type = 'district' and slug = 'bakirkoy';
update public.locations set slug = 'istanbul-umraniye' where type = 'district' and slug = 'umraniye';
update public.locations set slug = 'ankara-cankaya' where type = 'district' and slug = 'cankaya';
update public.locations set slug = 'ankara-kecioren' where type = 'district' and slug = 'kecioren';
update public.locations set slug = 'ankara-yenimahalle' where type = 'district' and slug = 'yenimahalle';
update public.locations set slug = 'izmir-konak' where type = 'district' and slug = 'konak';
update public.locations set slug = 'izmir-bornova' where type = 'district' and slug = 'bornova';
update public.locations set slug = 'izmir-karsiyaka' where type = 'district' and slug = 'karsiyaka';

on conflict (type, slug) do update set name = excluded.name, parent_id = excluded.parent_id;

update public.locations d
set lat = c.lat, lng = c.lng
from public.locations c
where d.type = 'district' and d.parent_id = c.id;

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1)),
    coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1)),
    public.unique_slug(coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1))),
    'buyer',
    nullif(new.raw_user_meta_data->>'phone', ''),
    nullif(new.raw_user_meta_data->>'city_id', '')::uuid,
    nullif(new.raw_user_meta_data->>'district_id', '')::uuid
  );
  return new;
end;
$$;


